# OccBin simulation options, error flags, periodic solutions and IRFs against Dynare 7.2 (port of pydyn's
# tests/test_occbin_options.py; references reference/occ_*.mat, regenerated by pydyn's reference/r_occbin_options.m).
# Every case compares the piecewise and linear paths (rtol 1e-10), the regime histories exactly and the error
# flag (310-313) of Dynare. The largest differences found are printed at the end.
using Test; include("common.jl")

const MAXDIFF = Dict{String,Float64}()
function note_diff!(group, a, b)
    d = maximum(abs.(a .- b))
    MAXDIFF[group] = max(get(MAXDIFF, group, 0.0), d)
    d
end
close_to(a, b, group) = (note_diff!(group, a, b); isapprox(a, b; rtol=1e-10, atol=1e-12))

load_ref_model(name) = load_copy(joinpath(REF, name * ".mod"))
tolist(x) = Int.(vec(collect(x isa AbstractArray ? x : [x])))
"Dynare's regime history as [[(regime, start) per constraint] per shock period]."
function ref_regimes(r, key, k)
    a = reshape(r[key], 2k, :)
    [[(tolist(a[2j-1, t]), tolist(a[2j, t])) for j in 1:k] for t in 1:size(a, 2)]
end

"Result of one simulation, or the error flag (310-313) if an OccbinError is thrown."
function run_sim(ob, shocks; kw...)
    try
        simulate(ob, shocks; kw...)
    catch e
        e isa OccbinError || rethrow()
        error_flag(e)
    end
end

"Compare one stored variant: error flag, paths, regime history."
function check_case(ob, r, name, shocks; k=1, group="options", kw...)
    flag = Int(r["$(name)_flag"])
    res = run_sim(ob, shocks; kw...)
    if flag != 0
        @test res == flag
        return nothing
    end
    @test res isa OccbinResult            # Dynare succeeded
    res isa OccbinResult || return nothing
    @test close_to(res.piecewise, r["$(name)_piecewise"], group)
    @test close_to(res.linear, r["$(name)_linear"], group)
    @test res.regime_history == ref_regimes(r, "$(name)_regime", k)
    res
end

"Error flag of every maxit in the sweep, and the paths at the first and last success."
function check_sweep(ob, r, name, shocks; group="options", kw...)
    maxits = Int.(vec(r["$(name)_maxits"]))
    flags = Int.(vec(r["$(name)_flags"]))
    got, paths = Int[], Dict{Int,Matrix{Float64}}()
    for mi in maxits
        res = run_sim(ob, shocks; maxit=mi, kw...)
        push!(got, res isa OccbinResult ? 0 : res)
        res isa OccbinResult && (paths[mi] = res.piecewise)
    end
    @test got == flags
    if haskey(r, "$(name)_first_maxit")
        @test close_to(paths[Int(r["$(name)_first_maxit"])], r["$(name)_first_piecewise"], group)
    end
    if haskey(r, "$(name)_last_piecewise")
        @test close_to(paths[maxits[end]], r["$(name)_last_piecewise"], group)
    else
        @test flags[end] != 0
    end
    flags
end

# ======================================================================== one constraint, two shocks
@testset "OccBin options: borrowing constraint (one constraint, two shocks)" begin
    m = load_ref_model("occ_borrcon")
    ob = Occbin(m)
    r = refmat("occ_borrcon.mat")
    S = Matrix{Float64}(r["S"])

    @testset "default and parameters" begin
        a = simulate(ob, S; periods=80)
        @test maximum(abs.(a.piecewise .- a.linear)) > 1e-2
        res = check_case(ob, r, "default", S; periods=80)
        @test isapprox(res.ys, vec(r["ys"]); rtol=1e-12)
        # the reference ran with the same parameters (the occbin switch is NaN in JDyn until the solver sets it)
        keep = [i for i in eachindex(m.params) if !startswith(m.param_names[i], "occbin_")]
        @test isapprox(m.params[keep], vec(r["params"])[keep]; rtol=1e-14)
    end
    @testset "maxit sweep and truncation" begin
        flags = check_sweep(ob, r, "sw_default", S; periods=80)
        @test flags[1] == 0 && all(==(311), flags[2:13]) && flags[end] == 0     # maxit=1 accepts the first guess
        check_case(ob, r, "maxit1", S; periods=80, maxit=1)
        @test maximum(abs.(r["maxit1_piecewise"] .- r["default_piecewise"])) > 1e-3   # maxit=1 is not converged
    end
    @testset "curb_retrench" begin
        check_case(ob, r, "curb", S; periods=80, curb_retrench=true)
        check_sweep(ob, r, "sw_curb", S; periods=80, curb_retrench=true)
    end
    @testset "endo_init" begin
        init = vec(Float64.(r["init"]))
        check_case(ob, r, "endo_init", S; periods=80, init=init)
        @test maximum(abs.(r["endo_init_piecewise"] .- r["default_piecewise"])) > 1e-3     # the option matters
        check_case(ob, r, "endo_init_noshock", zeros(1, 2); periods=80, init=init)
        @test m.endo_names[1] == "b" && m.endo_names[5] == "y"                           # declaration order
    end
    @testset "exo_pos" begin
        check_case(ob, r, "exo_v_only", S[:, [2]]; periods=80, exo_pos=[2])
        res = check_case(ob, r, "exo_swapped", S[:, [2, 1]]; periods=80, exo_pos=[2, 1])
        names = check_case(ob, r, "exo_swapped", S[:, [2, 1]]; periods=80, exo_pos=["v", "u"])
        @test res.piecewise == names.piecewise
        @test close_to(res.piecewise, r["default_piecewise"], "options")      # swapping columns and exo_pos reproduces the default
        @test res.exo_pos == [2, 1]
        @test_throws ArgumentError simulate(ob, S; exo_pos=[2])
    end
    @testset "max_check_ahead_periods" begin
        check_case(ob, r, "maxcheck8", S; periods=80, check_ahead_periods=8, max_check_ahead_periods=8)
        @test maximum(abs.(r["maxcheck8_piecewise"] .- r["default_piecewise"])) > 1e-2
        check_sweep(ob, r, "sw_maxcheck8", S; periods=80, check_ahead_periods=8, max_check_ahead_periods=8)
        check_case(ob, r, "maxcheck20_check10", S; periods=80, check_ahead_periods=10, max_check_ahead_periods=20)
        check_sweep(ob, r, "sw_maxcheck20_check10", S; periods=80, check_ahead_periods=10, max_check_ahead_periods=20)
        check_case(ob, r, "maxcheck8_check5", S; periods=80, check_ahead_periods=5, max_check_ahead_periods=8)
        # check-ahead too short but not capped: the horizon grows endogenously, the path is the default one
        check_case(ob, r, "check12", S; periods=80, check_ahead_periods=12)
        check_sweep(ob, r, "sw_check12", S; periods=80, check_ahead_periods=12)
        @test close_to(r["check12_piecewise"], r["default_piecewise"], "options")
    end
    @testset "reset options" begin
        check_case(ob, r, "reset_regime", S; periods=80, reset_regime_in_new_period=true)
        f_reset = check_sweep(ob, r, "sw_reset_regime", S; periods=80, reset_regime_in_new_period=true)
        @test f_reset != Int.(vec(r["sw_default_flags"]))              # the number of iterations needed changes
        kw = (; periods=80, check_ahead_periods=12, reset_regime_in_new_period=true, reset_check_ahead_periods_in_new_period=true)
        check_case(ob, r, "reset_both_check12", S; kw...)
        check_sweep(ob, r, "sw_reset_both_check12", S; kw...)
        # reset_check_ahead_periods without reset_regime does nothing
        check_case(ob, r, "reset_check_only_check12", S; periods=80, check_ahead_periods=12, reset_check_ahead_periods_in_new_period=true)
    end
    @testset "init_regime and init_binding_indicator" begin
        default = simulate(ob, S; periods=80)
        rh = default.regime_history
        check_case(ob, r, "maxit3", S; periods=80, maxit=3)            # without a guess maxit=3 fails (311)
        check_case(ob, r, "maxit3_guess_full", S; periods=80, maxit=3, init_regime=rh)
        @test close_to(r["maxit3_guess_full_piecewise"], r["default_piecewise"], "options")
        half = [[length(reg) > 1 ? (copy(reg), vcat(s[1], cld(s[2], 2), s[3:end])) : (copy(reg), copy(s)) for (reg, s) in per] for per in rh]
        check_case(ob, r, "maxit8_guess_half", S; periods=80, maxit=8, init_regime=half)
        check_case(ob, r, "maxit8", S; periods=80, maxit=8)
        f_half = check_sweep(ob, r, "sw_guess_half", S; periods=80, init_regime=half)
        @test f_half != Int.(vec(r["sw_default_flags"]))
        check_sweep(ob, r, "sw_guess_two", S; periods=80, init_regime=rh[1:2])
        g = [copy(p) for p in rh]
        g[1] = [([0, 1], [1, 5])]                                       # a guess that ends in the binding regime
        check_case(ob, r, "guess_binding_end", S; periods=80, init_regime=g)
        g = [copy(p) for p in rh]
        g[1] = [([1, 0], [1, 300])]                                     # longer than the check-ahead rows: error 312
        check_case(ob, r, "guess_long", S; periods=80, init_regime=g)
        bi = Bool.(r["bi12"])
        check_case(ob, r, "maxit3_bi12", S; periods=80, maxit=3, init_binding_indicator=bi)
        check_sweep(ob, r, "sw_bi12", S; periods=80, init_binding_indicator=bi)
        @test_throws ArgumentError simulate(ob, S; periods=80, init_binding_indicator=zeros(Bool, 250))
    end
    @testset "error codes are distinguishable" begin
        S = Matrix{Float64}(r["S"])
        e = try simulate(ob, S; periods=80, maxit=3); nothing catch e; e end
        @test e isa OccbinMaxitError && error_flag(e) == 311 && e.period == 1
        g = [[([1, 0], [1, 300])]]
        e = try simulate(ob, S; periods=80, init_regime=g); nothing catch e; e end
        @test e isa OccbinHorizonError && error_flag(e) == 312
        @test occursin("312", sprint(showerror, e))
    end
end

@testset "OccBin options from the .mod file (borrcon, simul_* options)" begin
    m = load_ref_model("occ_borrcon_opts")
    ob = Occbin(m)
    r = refmat("occ_borrcon_opts.mat")
    maxit, curb, check, maxcheck, reset, reset_check, periods = Float64.(vec(r["mod_opts"]))
    o = mod_options(ob)
    @test Dict(pairs(o)) == Dict(:maxit => Int(maxit), :curb_retrench => Bool(curb), :check_ahead_periods => Int(check), :max_check_ahead_periods => maxcheck,
                                 :reset_regime_in_new_period => Bool(reset), :reset_check_ahead_periods_in_new_period => Bool(reset_check), :periods => Int(periods))
    @test curb == 1 && reset == 1 && reset_check == 1
    res = simulate(ob)
    @test close_to(res.piecewise, r["mod_piecewise"], "options")
    @test close_to(res.linear, r["mod_linear"], "options")
    @test res.regime_history == ref_regimes(r, "mod_regime", 1)
    # setup.m keeps the shocked columns only (here u) and records their positions
    @test res.exo_pos == [Int(r["mod_exo_pos"])] && vec(res.shocks) == vec(r["mod_shocks"])
    @test maximum(abs.(simulate(ob, JDyn.surprise_shocks(ob)[1]; periods=80, exo_pos=[1]).piecewise .- res.piecewise)) > 1e-3   # the options matter
    # keywords override the file's options
    @test size(simulate(ob; periods=60).piecewise, 1) == 60 && size(res.piecewise, 1) == 80
    # options that belong to OccBin estimation and smoothing are not implemented: warned, not silently dropped
    m2 = build(read(joinpath(REF, "occ_borrcon_opts.mod"), String) * "\noccbin_setup(smoother_periods=3);\n"; name="occ_warn")
    @test_logs (:warn, r"smoother.periods") mod_options(Occbin(m2))
end

# ======================================================================== two constraints, cycling guesses
const PSETS = Dict(   # (psi, phi, rho) and shocks, as in reference/r_occbin_options.m
    "c1" => ((10.30721957177062, 0.9879452800064452, 0.7469193213904868), [0.17885813149410787, -0.18518412993264557, 0.09168812685568793]),
    "c3" => ((4.6525347234318675, 0.950930792986048, 0.5850521699901848), [0.03831108818687395, 0.08817287153074853, -0.0932996254397529]),
    "c4" => ((13.436741484971341, 0.9608110490106523, 0.5495106530269722), [0.1246837534942502, 0.037652096093670165, -0.3040040918655403]),
    "e1" => ((4.038590202884413, 0.9538230658935829, 0.5028849753522318), [0.278665132869575, -0.4631084100053847, -0.09791875946873171]))
const VARIANTS = [
    "default" => (;),
    "per" => (; periodic_solution=true),
    "per_loose" => (; periodic_solution=true, periodic_solution_strict=false),
    "per_loose_thr0" => (; periodic_solution=true, periodic_solution_strict=false, periodic_solution_threshold=0),
    "per_loose_thr3" => (; periodic_solution=true, periodic_solution_strict=false, periodic_solution_threshold=3),
    "loose_only" => (; periodic_solution_strict=false),
    "per_thr0" => (; periodic_solution=true, periodic_solution_threshold=0),
    "curb" => (; curb_retrench=true),
    "curb_per" => (; curb_retrench=true, periodic_solution=true),
    "curb_per_loose" => (; curb_retrench=true, periodic_solution=true, periodic_solution_strict=false),
    "maxit3" => (; maxit=3),
    "maxit2_per" => (; maxit=2, periodic_solution=true),
    "maxit1" => (; maxit=1)]

function rbc_occbin(m, pset)
    for (nm, v) in zip(("psi", "phi", "rho"), PSETS[pset][1])
        set_param!(m, nm, v)
    end
    Occbin(m)
end

@testset "OccBin: two constraints, cycling regime guesses" begin
    m = load_ref_model("occ_rbc_cyc")
    r = refmat("occ_rbc_cyc.mat")
    psets = sort(collect(keys(PSETS)))
    @testset "periodic variants $pset" for pset in psets
        ob = rbc_occbin(m, pset)
        S = reshape(PSETS[pset][2], :, 1)
        @test vec(S) == vec(Float64.(r["$(pset)_S"]))
        for (variant, kw) in VARIANTS
            check_case(ob, r, "$(pset)_$(variant)", S; k=2, periods=80, group="periodic", kw...)
        end
    end
    @testset "maxit sweeps" for pset in psets
        ob = rbc_occbin(m, pset)
        S = reshape(PSETS[pset][2], :, 1)
        check_sweep(ob, r, "$(pset)_sw_loose_only", S; group="periodic", periods=80, periodic_solution_strict=false)
        check_sweep(ob, r, "$(pset)_sw_per_loose", S; group="periodic", periods=80, periodic_solution=true, periodic_solution_strict=false)
    end
    @testset "error flags 310 to 313" begin
        seen = Set(Int(v) for (k, v) in r if endswith(k, "_flag") && v isa Real)
        @test issubset(Set([0, 310, 311, 313]), seen)
        for pset in psets
            ob = rbc_occbin(m, pset)
            S = reshape(PSETS[pset][2], :, 1)
            flags = Dict{String,Int}()
            for (v, kw) in VARIANTS
                try
                    simulate(ob, S; periods=80, kw...)
                    flags[v] = 0
                catch e
                    e isa OccbinError || rethrow()
                    flags[v] = error_flag(e)
                    @test 1 <= e.period <= size(S, 1)               # 1-based shock period that failed
                end
            end
            @test flags == Dict(v => Int(r["$(pset)_$(v)_flag"]) for (v, _) in VARIANTS)
        end
        @test OccbinPeriodicError <: OccbinError && error_flag(OccbinPeriodicError("", 1)) == 310
        @test error_flag(OccbinLoopError("", 1)) == 313 && error_flag(OccbinHorizonError("", 1)) == 312
    end
    @testset "periodic solution selects a guess" begin
        ob = rbc_occbin(m, "c1")
        S = reshape(PSETS["c1"][2], :, 1)
        res = simulate(ob, S; periods=80, periodic_solution=true)
        @test res.periodic == [false, true, false]                 # selected in the second shock period
        d = res.diagnostics[2]
        @test d.selected !== nothing && !d.violates[d.selected]
        @test maximum(abs.(res.piecewise .- res.linear)) > 1e-2     # a real piecewise solution
    end
    @testset "options from the .mod file" begin
        m2 = load_ref_model("occ_rbc_cyc")
        ob = Occbin(m2)
        maxit, per, thr, strict, periods = Float64.(vec(r["mod_opts"]))
        @test Dict(pairs(mod_options(ob))) == Dict(:periods => Int(periods), :maxit => Int(maxit), :periodic_solution => Bool(per),
                                                   :periodic_solution_threshold => Int(thr), :periodic_solution_strict => Bool(strict))
        @test per == 1 && strict == 0 && thr == 3
        res = simulate(ob)
        @test close_to(res.piecewise, r["mod_piecewise"], "periodic")
        @test close_to(res.linear, r["mod_linear"], "periodic")
        @test res.regime_history == ref_regimes(r, "mod_regime", 2)
        @test res.periodic == [false, false, true]
        e = try simulate(ob; periodic_solution=false, periodic_solution_strict=true); nothing catch e; e end   # without the options: 313
        @test e isa OccbinLoopError && error_flag(e) == 313
    end
end

@testset "OccBin: error_bind and error_relax of the constraints block" begin
    m = load_ref_model("occ_rbc_err")
    cons = Dict(c["name"] => c for c in m.occbin_constraints)
    @test !isempty(cons["INEG"]["error_bind"]) && !isempty(cons["IRR"]["error_relax"]) && isempty(cons["IRR"]["error_bind"])
    ob = Occbin(m)
    r = refmat("occ_rbc_err.mat")
    S = reshape(Float64.(vec(r["S"])), :, 1)
    for (name, kw) in (("default", (;)), ("per", (; periodic_solution=true)),
                       ("per_loose", (; periodic_solution=true, periodic_solution_strict=false)),
                       ("per_thr0", (; periodic_solution=true, periodic_solution_threshold=0)))
        check_case(ob, r, name, S; k=2, periods=80, group="errors", kw...)
    end
    res = check_case(ob, r, "mod", S; k=2, periods=80, group="errors", periodic_solution=true)
    @test res.diagnostics[3].selected == 2 && all(res.diagnostics[3].violates)    # both guesses violate: the error decides
    # the default errors (the reference run with the same parameters and shocks, no error_* expressions) pick the other guess
    m2 = load_ref_model("occ_rbc_cyc"); r2 = refmat("occ_rbc_cyc.mat")
    ob2 = rbc_occbin(m2, "e1")
    res2 = simulate(ob2, S; periods=80, periodic_solution=true)
    @test res2.diagnostics[3].selected == 1
    @test res2.regime_history != res.regime_history
    @test close_to(res2.piecewise, r2["e1_per_piecewise"], "errors")
    @test maximum(abs.(res.piecewise .- res2.piecewise)) > 1e-5
    # errors as the preprocessor defines them: abs(lhs - rhs) of bind / relax, or the given expressions
    z = zeros(2, ob.n) .+ ob.ys'
    b, rl, eb, er = check_constraints(ob, z)
    @test size(eb) == (2, 2)
    # INEG at the steady state (log_Invest - log(ss) = 0): default error abs(0 - (-1e-6)) = 1e-6; custom 1000*abs(0) = 0
    @test all(check_constraints(ob2, z)[3][:, 2] .≈ 1e-6) && all(eb[:, 2] .== 0.0)
    @test all(er[:, 1] .≈ 1.0)                              # IRR error_relax = 1 + abs(Lambda) = 1 at the steady state
    @test all(check_constraints(ob2, z)[4][:, 1] .== 0.0)   # default: abs(Lambda - 0)
end

# ======================================================================== IRFs
irf_arrays(r, prefix, exo, sign) = (r["$(prefix)_$(exo)_$(sign)_piecewise"], r["$(prefix)_$(exo)_$(sign)_linear"])

@testset "OccBin IRFs (Dynare's occbin.irf)" begin
    m = load_ref_model("occ_borrcon")
    ob = Occbin(m)
    r = refmat("occ_borrcon.mat")
    @testset "borrcon, defaults" begin
        out = irf_occbin(ob)            # Dynare defaults: stderr-sized shocks, both signs, 40 periods
        @test Set(keys(out)) == Set((e, s) for e in ("u", "v") for s in ("pos", "neg"))
        for ((exo, sign)) in keys(out)
            pw, lin = irf_arrays(r, "irf_default", exo, sign)
            @test size(pw) == (41, 8)
            @test close_to(out[(exo, sign)].piecewise, pw, "irf")
            @test close_to(out[(exo, sign)].linear, lin, "irf")
        end
        # state dependence: the positive u shock hits the constraint, the negative one does not
        pw, lin = irf_arrays(r, "irf_default", "u", "pos")
        @test maximum(abs.(pw .- lin)) > 1e-3
        pw, lin = irf_arrays(r, "irf_default", "u", "neg")
        @test maximum(abs.(pw .- lin)) < 1e-12
        @test Int(r["irf_stale_exo_pos_error"]) == 1     # Dynare 7.2 fails with a stale exo_pos, see below
    end
    @testset "borrcon, options" begin
        out = irf_occbin(ob; periods=30, shocksize=[0.3, 0.1], check_ahead_periods=12, maxit=25)
        for (exo, sign) in keys(out)
            pw, lin = irf_arrays(r, "irf_big", exo, sign)
            @test size(pw) == (31, 8)
            @test close_to(out[(exo, sign)].piecewise, pw, "irf")
            @test close_to(out[(exo, sign)].linear, lin, "irf")
        end
        out1 = irf_occbin(ob; periods=30, shocksize=0.3, exo_names=["u"], shocksigns=("pos",), check_ahead_periods=12, maxit=25)
        @test keys(out1) == [("u", "pos")]
        @test close_to(out1[("u", "pos")].piecewise, r["irf_big_u_pos_piecewise"], "irf")
    end
    @testset "irf(ob, impulse) is Dynare's response" begin
        size_ = sqrt(m.Sigma_e[1, 1])
        for (sign, sg) in (("pos", 1.0), ("neg", -1.0))
            got = irf(ob, [sg * size_, 0.0]; periods=41, check_ahead_periods=30)
            @test close_to(got, r["irf_default_u_$(sign)_piecewise"], "irf")
        end
        @test close_to(irf(ob, [0.0, 0.1]; periods=31, check_ahead_periods=12, maxit=25), r["irf_big_v_pos_piecewise"], "irf")
    end
    @testset "rbc, two constraints" begin
        m2 = load_ref_model("occ_rbc_cyc"); r2 = refmat("occ_rbc_cyc.mat")
        for (nm, v) in zip(("psi", "phi", "rho"), (5.0, 0.975, 0.9))
            set_param!(m2, nm, v)
        end
        ob2 = Occbin(m2)
        out = irf_occbin(ob2; periods=40, shocksize=0.04, check_ahead_periods=200)
        for (exo, sign) in keys(out)
            pw, lin = irf_arrays(r2, "irf", exo, sign)
            @test size(pw) == (41, 8)
            @test close_to(out[(exo, sign)].piecewise, pw, "irf")
            @test close_to(out[(exo, sign)].linear, lin, "irf")
        end
        pw, lin = irf_arrays(r2, "irf", "epsilon", "neg")
        @test maximum(abs.(pw .- lin)) > 1e-3
        # the default size (stderr 0.015) with the default check-ahead of 30 fails for this model (311), as in Dynare
        e = try irf_occbin(ob2); nothing catch e; e end
        @test e isa OccbinMaxitError && error_flag(e) == 311
        out = irf_occbin(ob2; periods=40, check_ahead_periods=200)
        for (exo, sign) in keys(out)
            @test close_to(out[(exo, sign)].piecewise, irf_arrays(r2, "irf_dflt", exo, sign)[1], "irf")
        end
    end
    @testset "plotted content: tidy table with a piecewise/linear column" begin
        out = irf_occbin(ob; periods=30, shocksize=[0.3, 0.1], check_ahead_periods=12, maxit=25)
        tab = irf_table(out)
        @test length(tab) == 2 * 2 * 8 * 2 * 31                      # signs x shocks x variables x solutions x periods
        @test Set(r.solution for r in tab) == Set(["piecewise", "linear"])
        row = only(r for r in tab if r.shock == "u" && r.sign == "pos" && r.variable == "lb" && r.solution == "piecewise" && r.period == 5)
        @test row.value == out[("u", "pos")].piecewise[5, findfirst(==("lb"), m.endo_names)]
        sub = irf_table(out; variables=["c", "b"])
        @test length(sub) == 2 * 2 * 2 * 2 * 31 && unique(r.variable for r in sub) == ["c", "b"]
        f = JDyn.write_csv(joinpath(mktempdir(), "occbin_irf.csv"), tab)
        lines = readlines(f)
        @test lines[1] == "shock,sign,variable,period,solution,value" && length(lines) == length(tab) + 1
        @test_throws ArgumentError irf_table(out; variables=["nonexistent"])
    end
end

# ======================================================================== one constraint, cycling guesses
const PSETS1 = Dict("a" => ((8.20453071654218, 0.43376653874397436, 4.162224515697595), [-0.006401074156627856, 0.21600250881228591, -0.1255342530145265]),
                    "b" => ((29.06953055729189, 0.3407807947098334, 0.7619883020628548), [-0.06332487508731809, -0.06344217665694422]),
                    "c" => ((1.5460870251082188, 0.4426697608503545, 1.5078256168794189), [0.060713476541191136]))
const V1 = ["default", "per", "per_loose", "per_loose_thr0", "loose_only", "curb", "curb_per", "maxit3"]

@testset "OccBin: one constraint, cycling regime guesses" begin
    m = load_ref_model("occ_rbc1")
    r = refmat("occ_rbc1.mat")
    variants = Dict(VARIANTS)
    @testset "pset $pset" for pset in sort(collect(keys(PSETS1)))
        for (nm, v) in zip(("psi", "rho", "sigma"), PSETS1[pset][1])
            set_param!(m, nm, v)
        end
        ob = Occbin(m)
        @test ob.k == 1
        S = reshape(PSETS1[pset][2], :, 1)
        for v in V1
            check_case(ob, r, "$(pset)_$(v)", S; k=1, periods=80, group="periodic1", variants[v]...)
        end
    end
    seen = Set(Int(v) for (k, v) in r if endswith(k, "_flag") && v isa Real)
    @test issubset(Set([0, 310, 311, 313]), seen)
end

# ======================================================================== Dynare 7.2 defects
@testset "OccBin: Dynare 7.2 defects, corrected by default and replicable" begin
    m = load_ref_model("occ_borrcon")
    ob = Occbin(m)
    r = refmat("occ_borrcon.mat")
    S = Matrix{Float64}(r["S"])
    @testset "check_ahead_periods above max_check_ahead_periods" begin
        # Dynare 7.2's occbin.solver intends to lower check_ahead_periods to the maximum but its message uses an
        # undefined variable and fails; JDyn lowers it (the path is the one with check_ahead = max = 8) ...
        res = simulate(ob, S; periods=80, check_ahead_periods=10, max_check_ahead_periods=8)
        @test close_to(res.piecewise, r["maxcheck8_piecewise"], "options")
        # ... unless asked to reproduce the failure
        @test_throws OccbinDynareBug simulate(ob, S; periods=80, check_ahead_periods=10, max_check_ahead_periods=8, replicate_dynare_bugs=true)
        @test simulate(ob, S; periods=80, check_ahead_periods=8, max_check_ahead_periods=8, replicate_dynare_bugs=true).piecewise == res.piecewise
    end
    @testset "occbin.irf with a stale exo_pos" begin
        # occ_borrcon_opts has two shocks but shocks(surprise) only for u: occbin_setup leaves exo_pos = 1
        mo = load_ref_model("occ_borrcon_opts")
        obo = Occbin(mo)
        @test JDyn.surprise_shocks(obo)[2] == [1]
        e = try irf_occbin(obo; replicate_dynare_bugs=true); nothing catch e; e end
        @test e isa OccbinDynareBug && occursin("exo_pos", e.msg)
        out = irf_occbin(obo)                                   # corrected: all shocks, same model as occ_borrcon
        for (exo, sign) in keys(out)
            @test close_to(out[(exo, sign)].piecewise, irf_arrays(r, "irf_default", exo, sign)[1], "irf")
        end
        # a model without a shocks(surprise) block has exo_pos = 1:n_exo: nothing to replicate
        @test length(irf_occbin(ob; replicate_dynare_bugs=true).responses) == 4
    end
end

